SafeAddString(DE_SETTINGS_MINIMAL_MODE, "Минимальный режим", 1)
SafeAddString(DE_SETTINGS_MINIMAL_MODE_TT, "Показывает только компактную строку статуса без зоны, названия события и раздела. Также переключается маленькой кнопкой в правом верхнем углу окна статуса.", 1)
