SafeAddString(DE_SETTINGS_SHOW_MINIMAL_TOGGLE_BUTTON, "Показывать кнопку минимального режима", 1)
SafeAddString(DE_SETTINGS_SHOW_MINIMAL_TOGGLE_BUTTON_TT, "Показывает маленькую кнопку в правом верхнем углу окна статуса для переключения минимального режима. Если она скрыта, минимальный режим по-прежнему доступен через настройку «Минимальный режим».", 1)
SafeAddString(DE_SETTINGS_HIDE_MENUS, "Скрыть в меню", 1)
