SafeAddString(DE_SETTINGS_ADDON_ENABLED, "Аддон активирован", 1)
SafeAddString(DE_SETTINGS_ADDON_ENABLED_TT, "Включает или выключает аддон полностью. При выключении никакие события времени выполнения, циклы обновления, обратные вызовы сцен, звуки или дисплеи не регистрируются.", 1)
SafeAddString(DE_SETTINGS_SECTION_RESPAWN_DESC, "После обнаруженного окончания события показывает обратный отсчёт, окно появления и превышение ожидаемого времени. Самое раннее и ожидаемое время начала можно настроить ниже для каждого события.", 1)
